-- ══════════════════════════════════════════════════════════════════
--  SmartWaste Cusco — Script unificado v2.0
--  Incluye: esquema + 10 sectores + rutas trazadas por calles reales (OSRM) + 8 conductores
-- ══════════════════════════════════════════════════════════════════
CREATE DATABASE IF NOT EXISTS smartwaste_db CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE smartwaste_db;

SET FOREIGN_KEY_CHECKS = 0;
DROP TABLE IF EXISTS recolecciones;
DROP TABLE IF EXISTS asignacion_rutas;
DROP TABLE IF EXISTS conductores;
DROP TABLE IF EXISTS notificaciones;
DROP TABLE IF EXISTS reportes;
DROP TABLE IF EXISTS horarios;
DROP TABLE IF EXISTS rutas;
DROP TABLE IF EXISTS camiones;
DROP TABLE IF EXISTS tipos_residuos;
DROP TABLE IF EXISTS usuarios;
DROP TABLE IF EXISTS zonas;
DROP TABLE IF EXISTS roles;
DROP TABLE IF EXISTS alertas;
SET FOREIGN_KEY_CHECKS = 1;

-- ── 1. ROLES ──────────────────────────────────────────────────────
CREATE TABLE roles (
    id     INT AUTO_INCREMENT PRIMARY KEY,
    nombre VARCHAR(50) NOT NULL UNIQUE
);
INSERT INTO roles (nombre) VALUES
('ciudadano'),('operadorVehiculo'),('administrador'),('supervisorMunicipal');

-- ── 2. ZONAS (10 sectores del distrito de Cusco) ──────────────────
CREATE TABLE zonas (
    id          INT AUTO_INCREMENT PRIMARY KEY,
    nombre      VARCHAR(100) NOT NULL,
    descripcion TEXT,
    estado      ENUM('activo','inactivo') DEFAULT 'activo'
);
INSERT INTO zonas (nombre, descripcion) VALUES
('Centro Histórico', 'Zona monumental y comercial'), -- 1
('San Blas', 'Barrio artesanal y turístico'), -- 2
('Santa Ana', 'Sector Santa Ana – zona residencial e histórica'), -- 3
('San Pedro', 'Sector San Pedro – zona comercial y de mercados'), -- 4
('Tica Tica', 'Sector Tica Tica – zona residencial'), -- 5
('Independencia', 'Sector Independencia – zona residencial'), -- 6
('Ayuda Mutua', 'Sector Ayuda Mutua – zona residencial'), -- 7
('Balconcillo', 'Sector Balconcillo – zona residencial'), -- 8
('Sacsayhuamán', 'Sector Sacsayhuamán – zona arqueológica y residencial'), -- 9
('Ccoripata', 'Sector Ccoripata / Qoripata – zona residencial'); -- 10

-- ── 3. USUARIOS ───────────────────────────────────────────────────
CREATE TABLE usuarios (
    id                INT AUTO_INCREMENT PRIMARY KEY,
    nombres           VARCHAR(100) NOT NULL,
    apellidos         VARCHAR(100) NOT NULL,
    dni               VARCHAR(8)   UNIQUE,
    correo            VARCHAR(100) NOT NULL UNIQUE,
    contrasena        VARCHAR(255),
    rol_id            INT DEFAULT 1,
    zona_id           INT,
    latitud           DECIMAL(10,7) DEFAULT NULL,
    longitud          DECIMAL(10,7) DEFAULT NULL,
    proveedor_social  ENUM('local','google','facebook') DEFAULT 'local',
    proveedor_id      VARCHAR(255) DEFAULT NULL,
    foto_perfil       VARCHAR(255) DEFAULT NULL,
    estado            ENUM('activo','inactivo') DEFAULT 'activo',
    fecha_creacion    TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (rol_id)  REFERENCES roles(id),
    FOREIGN KEY (zona_id) REFERENCES zonas(id)
);
