-- ── 8. HORARIOS ───────────────────────────────────────────────────
CREATE TABLE horarios (
    id              INT AUTO_INCREMENT PRIMARY KEY,
    ruta_id         INT,
    dia_semana      ENUM('Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'),
    hora_inicio     TIME,
    hora_fin        TIME,
    tipo_residuo_id INT,
    FOREIGN KEY (ruta_id)         REFERENCES rutas(id),
    FOREIGN KEY (tipo_residuo_id) REFERENCES tipos_residuos(id)
);
-- Grupo A (rutas 1-4): Lunes/Jueves y Martes/Viernes
-- Grupo B (rutas 5-7): Lunes/Jueves y Martes/Viernes
-- Grupo C (rutas 8-10): Miércoles/Viernes/Sábado (rotando de a pares)
-- Ruta 1 (Centro Histórico) sólo se recoge de noche (8-11 pm) para no afectar el turismo.
-- El resto de rutas usa franjas diurnas de 3 horas: 9am-12pm, 10am-1pm, 2-5pm y 3-6pm.
INSERT INTO horarios (ruta_id, dia_semana, hora_inicio, hora_fin, tipo_residuo_id) VALUES
