-- ── 9. ASIGNACIÓN DE RUTAS ────────────────────────────────────────
CREATE TABLE asignacion_rutas (
    id               INT AUTO_INCREMENT PRIMARY KEY,
    camion_id        INT,
    ruta_id          INT,
    operador_id      INT,
    fecha_asignacion DATE NOT NULL,
    hora_inicio      TIME NULL,
    hora_fin         TIME NULL,
    estado           ENUM('pendiente','en_proceso','completado','cancelado') DEFAULT 'pendiente',
    FOREIGN KEY (camion_id)   REFERENCES camiones(id),
    FOREIGN KEY (ruta_id)     REFERENCES rutas(id),
    FOREIGN KEY (operador_id) REFERENCES usuarios(id)
);
-- Ejemplo semana 1 de la rotación (Lunes): Grupo A=Pedro, Grupo B=Carlos
-- Grupo C (Raúl) no trabaja Lunes, entra Miércoles/Viernes/Sábado
INSERT INTO asignacion_rutas (camion_id, ruta_id, operador_id, fecha_asignacion, hora_inicio, hora_fin, estado) VALUES
(1, 1, 2, CURDATE(), '20:00:00', '23:00:00', 'pendiente'),
(1, 2, 2, CURDATE(), '09:00:00', '12:00:00', 'pendiente'),
(2, 5, 5, CURDATE(), '15:00:00', '18:00:00', 'pendiente'),
(2, 6, 5, CURDATE(), '09:00:00', '12:00:00', 'en_proceso');

-- ── 10. RECOLECCIONES ─────────────────────────────────────────────
CREATE TABLE recolecciones (
    id               INT AUTO_INCREMENT PRIMARY KEY,
    asignacion_id    INT,
    operador_id      INT NOT NULL,
    zona_id          INT,
    tipo_residuo_id  INT,
    cantidad_kg      DECIMAL(10,2),
    observaciones    TEXT,
    estado           ENUM('en_proceso','completado') DEFAULT 'en_proceso',
    fecha_inicio     TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_completado TIMESTAMP NULL,
    FOREIGN KEY (asignacion_id)   REFERENCES asignacion_rutas(id),
    FOREIGN KEY (operador_id)     REFERENCES usuarios(id),
    FOREIGN KEY (zona_id)         REFERENCES zonas(id),
    FOREIGN KEY (tipo_residuo_id) REFERENCES tipos_residuos(id)
);

-- ── 11. REPORTES ──────────────────────────────────────────────────
CREATE TABLE reportes (
    id                   INT AUTO_INCREMENT PRIMARY KEY,
    usuario_id           INT,
    foto_url             VARCHAR(255),
    latitud              DECIMAL(10,8),
    longitud             DECIMAL(11,8),
    tipo_residuo_id      INT,
    descripcion          TEXT,
    numero_ticket        VARCHAR(20) UNIQUE,
    estado               ENUM('enviado','leido','en_proceso','completado','cancelado') DEFAULT 'enviado',
    supervisor_id        INT NULL,
    respuesta_supervisor TEXT NULL,
    fecha_respuesta      TIMESTAMP NULL,
    fecha_creacion       TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    fecha_actualizacion  TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    FOREIGN KEY (usuario_id)      REFERENCES usuarios(id),
    FOREIGN KEY (tipo_residuo_id) REFERENCES tipos_residuos(id),
    FOREIGN KEY (supervisor_id)   REFERENCES usuarios(id)
);
-- usuario_id 1=Juan (zona Centro Histórico), 9=Lucía (zona San Blas); supervisor_id 4=Maria
INSERT INTO reportes (usuario_id, foto_url, latitud, longitud, tipo_residuo_id, descripcion, numero_ticket, estado, supervisor_id, respuesta_supervisor, fecha_respuesta) VALUES
